const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const {createHash} = require('node:crypto');
const root = path.resolve(__dirname, '../..');
const sourceRevision = 'f72c289430b77d32eb888a01403f95a9a28f03af';
const readResults = name => fs.readFileSync(path.join(__dirname, name + '.log'), 'utf8').split(/\r?\n/)
    .filter(line => line.startsWith('NATIVE_RESULT ')).map(line => JSON.parse(line.slice(14)));
const traced = readResults('traced-probes'), controls = readResults('control-probes');
const results = [...traced, ...controls];
assert.equal(traced.length, 7);
assert(results.every(result => result.sourceRevision === sourceRevision && result.harnessRevision === sourceRevision && !result.dirty));
assert.equal(new Set(results.map(result => result.artifactDigest)).size, 1);
assert(traced.every(result => result.metrics.contentLoads));
assert(controls.every(result => !Object.hasOwn(result.metrics, 'contentLoads')));
const summarize = (rows, requested) => ({requested, completed: rows.length, passed: rows.filter(row => row.ok).length,
    failed: rows.filter(row => !row.ok).length, skipped: requested - rows.length,
    ownedWorkersClosed: rows.every(row => !row.workerStillRunning && !row.retainedProfilePath)});
const report = {
    localDate: '2026-11-20', platform: process.platform, node: process.version, sourceRevision,
    artifactDigest: results[0].artifactDigest,
    scope: 'Diagnostic runs after restart. Traced results include instrumentation overhead; controls are single pilots, not a repeated capacity certification. No deadlines or assertions were relaxed.',
    verification: {lint: 'passed', typecheck: 'passed', source: {passed: 311, failed: 0, durationMs: 129012.2757},
        browser: {passed: 62, failed: 0, retries: 0, reportedMinutes: 13.4}, build: {passed: true, reportedMB: 41.45},
        restrictedShell: 'Initial source run passed 310/311; owned-process cleanup failed in the restricted shell. Verified orphan test workers were stopped. Supervisor tests passed 11/11 and the full source suite passed 311/311 with process-control access; no application changes were needed.'},
    summary: {traced: summarize(traced, 10), controls: summarize(controls, 2)},
    capture: {script: fs.readFileSync(__filename, 'utf8'), logs: Object.fromEntries(['traced-probes', 'control-probes'].map(name =>
        [name, {sha256: createHash('sha256').update(fs.readFileSync(path.join(__dirname, name + '.log'))).digest('hex')}]))},
    testedArtifactFiles: JSON.parse(fs.readFileSync(path.join(__dirname, 'tested-build-manifest.json'), 'utf8')),
    traced, controls
};
fs.writeFileSync(path.join(root, 'docs/evidence/reference-load-2026-11-20.json'), JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify({artifactDigest: report.artifactDigest, summary: report.summary,
    runs: results.map(row => ({label: row.label, mode: row.mode, sample: row.sample + 1, ok: row.ok,
        readyMs: row.metrics.workspaceReady?.ms, revealMs: row.metrics.revealMixedContentKinds?.ms,
        imageStages: row.metrics.contentLoads?.completed.filter(record => record.entityId === 'native:object:00003')
            .map(({phase, durationMs, status, occurrenceId}) => ({phase, durationMs, status, occurrenceId})),
        errors: row.errors}))}, null, 2));
